package com.temporosstracker;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "Tempoross Solo Tracker",
    description = "Interactive checklist + storm intensity notification for solo Tempoross",
    tags = {"tempoross", "minigame", "tracker", "checklist"}
)
public class TemporossSoloTrackerPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(TemporossSoloTrackerPlugin.class);

    // Shipping default: no debug logging. Keep the hooks so we can re-enable quickly later.
    private static final boolean DEBUG = false;

    // Verified lobby/waiting area region ID (Jackson)
    private static final int TEMPOROSS_LOBBY_REGION_ID = 12588;

    // Verified: storm intensity text widget (Jackson)
    private static final int STORM_INTENSITY_WIDGET_GROUP_ID = 437;
    private static final int STORM_INTENSITY_WIDGET_CHILD_ID = 55;
    private static final Pattern STORM_INTENSITY_PATTERN = Pattern.compile("(\\d{1,3})");

    private static final String SOLO_START_OPTION = "Solo-start";
    private static final String SOLO_START_TARGET = "Rope ladder";

    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private Notifier notifier;

    @Inject
    private TemporossSoloTrackerConfig config;

    private TemporossSoloTrackerPanel panel;
    private NavigationButton navButton;

    // Solo-only gate: only true after the player clicks Solo-start on the boat.
    private boolean soloRunActive = false;

    private int lastRegionId = -1;
    private int lastStormIntensity = -1;

    @Provides
    TemporossSoloTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(TemporossSoloTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        List<PhaseStep> checklist = ChecklistDefinition.createChecklist();
        TrackerState trackerState = TrackerState.fromChecklist(checklist);
        panel = new TemporossSoloTrackerPanel(checklist, trackerState);
        panel.setOnReset(() -> {
            lastStormIntensity = -1;
        });

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        navButton = NavigationButton.builder()
            .tooltip("Tempoross Solo Tracker")
            .icon(icon)
            .panel(panel)
            .priority(5)
            .build();

        clientToolbar.addNavigation(navButton);

        lastRegionId = getRegionIdSafe();
        soloRunActive = false;
        lastStormIntensity = -1;
    }

    @Override
    protected void shutDown()
    {
        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }
        panel = null;

        soloRunActive = false;
        lastRegionId = -1;
        lastStormIntensity = -1;
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e)
    {
        // Start tracking only for solo runs.
        String opt = e.getMenuOption();
        if (!SOLO_START_OPTION.equals(opt))
        {
            return;
        }

        String target = Text.removeTags(e.getMenuTarget());
        if (!SOLO_START_TARGET.equals(target))
        {
            return;
        }

        soloRunActive = true;
        lastStormIntensity = -1;

        if (DEBUG)
        {
            log.debug("Solo-start clicked: action={} id={} p0={} p1={} regionId={}",
                e.getMenuAction(), e.getId(), e.getParam0(), e.getParam1(), getRegionIdSafe());
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        int regionId = getRegionIdSafe();

        // Reset checklist ONLY when the player returns to the lobby region (game ended).
        if (config.autoReset() && regionId == TEMPOROSS_LOBBY_REGION_ID && lastRegionId != TEMPOROSS_LOBBY_REGION_ID)
        {
            soloRunActive = false;
            lastStormIntensity = -1;
            if (panel != null)
            {
                panel.resetChecklist();
            }
        }
        lastRegionId = regionId;

        // Storm intensity notification: solo-only, fight-UI-only, and rising-edge like Idle Notifier.
        if (!soloRunActive)
        {
            return;
        }

        StormIntensityReading reading = readStormIntensity();
        if (!reading.fightUiPresent)
        {
            return;
        }

        int intensity = reading.intensity;
        if (intensity < 0)
        {
            if (DEBUG)
            {
                log.debug("Storm notify debug: rawText='{}' parsed=-1 threshold={} lastIntensity={}",
                    reading.rawText, config.stormNotifyThreshold(), lastStormIntensity);
            }
            return;
        }

        int threshold = config.stormNotifyThreshold();
        boolean crossedUp = (lastStormIntensity < threshold) && (intensity >= threshold);
        if (crossedUp)
        {
            notifier.notify(config.stormNotifyNotification(), "Storm intensity at " + intensity + "%");
        }

        if (DEBUG)
        {
            log.debug("Storm notify debug: intensity={} threshold={} lastIntensity={} fired={} rawText='{}'",
                intensity, threshold, lastStormIntensity, crossedUp, reading.rawText);
        }

        lastStormIntensity = intensity;
    }

    private StormIntensityReading readStormIntensity()
    {
        Widget widget = client.getWidget(STORM_INTENSITY_WIDGET_GROUP_ID, STORM_INTENSITY_WIDGET_CHILD_ID);
        if (widget == null)
        {
            return new StormIntensityReading(-1, null, false);
        }

        String rawText = widget.getText();
        int value = parseStormIntensity(rawText);
        return new StormIntensityReading(value, rawText, true);
    }

    private int parseStormIntensity(String text)
    {
        if (text == null)
        {
            return -1;
        }

        Matcher matcher = STORM_INTENSITY_PATTERN.matcher(text);
        if (!matcher.find())
        {
            return -1;
        }

        try
        {
            int value = Integer.parseInt(matcher.group(1));
            return value >= 0 && value <= 100 ? value : -1;
        }
        catch (NumberFormatException ignored)
        {
            return -1;
        }
    }

    private int getRegionIdSafe()
    {
        if (client == null || client.getLocalPlayer() == null)
        {
            return -1;
        }
        return client.getLocalPlayer().getWorldLocation().getRegionID();
    }

    private static final class StormIntensityReading
    {
        private final int intensity;
        private final String rawText;
        private final boolean fightUiPresent;

        private StormIntensityReading(int intensity, String rawText, boolean fightUiPresent)
        {
            this.intensity = intensity;
            this.rawText = rawText;
            this.fightUiPresent = fightUiPresent;
        }
    }
}

package com.temporosstracker;

import java.util.ArrayList;
import java.util.List;

public final class ChecklistDefinition
{
    private ChecklistDefinition()
    {
    }

    public static List<PhaseStep> createChecklist()
    {
        List<PhaseStep> steps = new ArrayList<>();

        addPhase(steps, 1, "Phase 1 — Double Spot Fishing Setup", new String[]
        {
            "Fish up to 8 at first spot",
            "Cook fish until double spot appears",
            "Move to double spot",
            "Fish until 16 fish obtained at double spot",
            "Finish cooking all 16 fish",
            "Fill cannon with all 16 fish",
            "Put out any fires on the way back to fishing"
        });

        addPhase(steps, 2, "Phase 2 — Prep and First Damage Phase", new String[]
        {
            "Fish full inventory; utilize double spot as much as possible",
            "Cook full inventory — storm intensity must stay below 93%!",
            "Fill cannon (full inventory)",
            "Damage Tempoross to ~60%"
        }, false, new int[] {2});

        addPhase(steps, 3, "Recovery Phase — Catch Up", new String[]
        {
            "Optional recovery as needed: finish fishing/cooking to recover the total 19 fish if time ran out in Phase 2"
        }, true);

        addPhase(steps, 4, "Phase 3 — Full Inventory and Second Damage Phase", new String[]
        {
            "Fish full inventory",
            "Cook full inventory — storm intensity must stay below 93%!",
            "Fill cannon (full inventory)",
            "Damage Tempoross to ~30%"
        }, false, new int[] {2});

        addPhase(steps, 5, "Phase 4 — Double Fish, Enrage Skip, and Final Damage", new String[]
        {
            "Fish and cook full inventory; utilize double spot as much as possible",
            "Drop all (19) cooked fish at second cannon",
            "Fish and cook 16; utilize double spot as much as possible",
            "Fill first cannon with 16 fish",
            "Pick up full inventory of cooked fish at second cannon",
            "Fill second cannon (full inventory)",
            "Damage Tempoross to 0% to finish with 10 permits"
        });

        return steps;
    }

    private static void addPhase(List<PhaseStep> steps, int phaseNumber, String phaseName, String[] labels)
    {
        addPhase(steps, phaseNumber, phaseName, labels, false, null);
    }

    private static void addPhase(
        List<PhaseStep> steps,
        int phaseNumber,
        String phaseName,
        String[] labels,
        boolean optional
    )
    {
        addPhase(steps, phaseNumber, phaseName, labels, optional, null);
    }

    private static void addPhase(
        List<PhaseStep> steps,
        int phaseNumber,
        String phaseName,
        String[] labels,
        boolean optional,
        int[] warningSteps
    )
    {
        for (int i = 0; i < labels.length; i++)
        {
            int stepNumber = i + 1;
            boolean warning = isWarningStep(stepNumber, warningSteps);
            steps.add(new PhaseStep(phaseNumber, phaseName, stepNumber, labels[i], optional, warning));
        }
    }

    private static boolean isWarningStep(int stepNumber, int[] warningSteps)
    {
        if (warningSteps == null)
        {
            return false;
        }
        for (int warningStep : warningSteps)
        {
            if (warningStep == stepNumber)
            {
                return true;
            }
        }
        return false;
    }
}

package com.temporosstracker;

public class PhaseStep
{
    private final int phaseNumber;
    private final String phaseName;
    private final int stepIndex;
    private final String label;
    private final boolean optional;
    private final boolean warning;
    private boolean checked;

    public PhaseStep(int phaseNumber, String phaseName, int stepIndex, String label, boolean optional)
    {
        this(phaseNumber, phaseName, stepIndex, label, optional, false);
    }

    public PhaseStep(
        int phaseNumber,
        String phaseName,
        int stepIndex,
        String label,
        boolean optional,
        boolean warning
    )
    {
        this.phaseNumber = phaseNumber;
        this.phaseName = phaseName;
        this.stepIndex = stepIndex;
        this.label = label;
        this.optional = optional;
        this.warning = warning;
        this.checked = false;
    }

    public int getPhaseNumber()
    {
        return phaseNumber;
    }

    public String getPhaseName()
    {
        return phaseName;
    }

    public int getStepIndex()
    {
        return stepIndex;
    }

    public String getLabel()
    {
        return label;
    }

    public boolean isOptional()
    {
        return optional;
    }

    public boolean isWarning()
    {
        return warning;
    }

    public boolean isChecked()
    {
        return checked;
    }

    public void setChecked(boolean checked)
    {
        this.checked = checked;
    }
}

package com.temporosstracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * In-memory checklist state.
 *
 * Highlighting rule (per Jackson): highlight the step immediately after the
 * lowest checked box, regardless of gaps above. If nothing is checked, highlight
 * the first step. If all are checked, no active step.
 */
public class TrackerState
{
    private final List<PhaseStep> steps;

    private TrackerState(List<PhaseStep> steps)
    {
        this.steps = new ArrayList<>(steps);
    }

    public static TrackerState fromChecklist(List<PhaseStep> checklist)
    {
        return new TrackerState(copySteps(checklist));
    }

    public List<PhaseStep> getSteps()
    {
        return Collections.unmodifiableList(steps);
    }

    public int size()
    {
        return steps.size();
    }

    public PhaseStep getStep(int index)
    {
        if (index < 0 || index >= steps.size())
        {
            throw new IllegalArgumentException("Index out of range: " + index);
        }
        return steps.get(index);
    }

    /**
     * @return the active step index, or -1 if all steps are checked.
     */
    public int getActiveStepIndex()
    {
        int lastChecked = -1;
        for (int i = 0; i < steps.size(); i++)
        {
            if (steps.get(i).isChecked())
            {
                lastChecked = i;
            }
        }

        int next = lastChecked + 1;
        if (next < 0)
        {
            next = 0;
        }
        return next >= steps.size() ? -1 : next;
    }

    public void setChecked(int index, boolean checked)
    {
        getStep(index).setChecked(checked);
    }

    public void reset()
    {
        for (PhaseStep step : steps)
        {
            step.setChecked(false);
        }
    }

    private static List<PhaseStep> copySteps(List<PhaseStep> checklist)
    {
        List<PhaseStep> copies = new ArrayList<>(checklist.size());
        for (PhaseStep source : checklist)
        {
            PhaseStep copy = new PhaseStep(
                source.getPhaseNumber(),
                source.getPhaseName(),
                source.getStepIndex(),
                source.getLabel(),
                source.isOptional(),
                source.isWarning()
            );
            copy.setChecked(source.isChecked());
            copies.add(copy);
        }
        return copies;
    }
}

package com.temporosstracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class TemporossSoloTrackerPanel extends PluginPanel
{
    private static final Color ACTIVE_STEP_COLOR = new Color(255, 253, 231);
    private static final Color GOLD_COLOR = new Color(242, 140, 0);

    // Width hint for HTML-wrapped checkbox labels (RuneLite sidebar is narrow).
    private static final int LABEL_WRAP_PX = 145;

    private final JButton resetButton;
    private final JPanel content;
    private final TrackerState trackerState;
    private final List<StepRow> stepRows = new ArrayList<>();

    private Runnable onReset;

    public TemporossSoloTrackerPanel()
    {
        this(ChecklistDefinition.createChecklist(), null);
    }

    public TemporossSoloTrackerPanel(List<PhaseStep> checklist, TrackerState trackerState)
    {
        TrackerState state = trackerState != null ? trackerState : TrackerState.fromChecklist(checklist);
        this.trackerState = state;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        content = new JPanel();
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        JLabel title = new JLabel("Tempoross Solo Tracker");
        title.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        content.add(title);

        resetButton = new JButton("Reset");
        resetButton.setAlignmentX(LEFT_ALIGNMENT);
        resetButton.addActionListener(event -> handleReset());
        content.add(resetButton);

        buildChecklist(state);
        updateActiveStepHighlight();

        // RuneLite already provides scrolling for sidebar panels.
        add(content, BorderLayout.CENTER);
    }

    public void setOnReset(Runnable onReset)
    {
        this.onReset = onReset;
    }

    /**
     * Programmatic reset (used by the plugin when auto-reset triggers).
     */
    public void resetChecklist()
    {
        handleReset();
    }

    public TrackerState getTrackerState()
    {
        return trackerState;
    }

    private void buildChecklist(TrackerState state)
    {
        int currentPhase = -1;
        for (int i = 0; i < state.size(); i++)
        {
            PhaseStep step = state.getStep(i);
            if (step.getPhaseNumber() != currentPhase)
            {
                currentPhase = step.getPhaseNumber();
                boolean phaseOptional = isPhaseOptional(state, currentPhase);
                content.add(createPhaseHeader(step.getPhaseName(), phaseOptional));
            }

            JCheckBox checkbox = new JCheckBox(formatLabel(step.getLabel(), step.isChecked()), step.isChecked());
            checkbox.setAlignmentX(LEFT_ALIGNMENT);
            checkbox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            checkbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
            checkbox.setOpaque(false);

            JPanel row = new JPanel(new BorderLayout());
            row.setAlignmentX(LEFT_ALIGNMENT);
            row.setBackground(ColorScheme.DARK_GRAY_COLOR);
            row.setBorder(new EmptyBorder(2, 0, 2, 0));
            row.add(checkbox, BorderLayout.WEST);

            int stepIndex = i;
            checkbox.addActionListener(event -> {
                trackerState.setChecked(stepIndex, checkbox.isSelected());
                updateActiveStepHighlight();
            });

            stepRows.add(new StepRow(stepIndex, row, checkbox, step.getLabel(), checkbox.getFont(), step.isWarning()));
            content.add(row);
        }
    }

    private JLabel createPhaseHeader(String phaseName, boolean optional)
    {
        JLabel header = new JLabel(optional ? phaseName + " (Optional)" : phaseName);
        header.setAlignmentX(LEFT_ALIGNMENT);
        header.setForeground(GOLD_COLOR);
        Font baseFont = header.getFont().deriveFont(Font.BOLD, 13f);
        if (optional)
        {
            baseFont = baseFont.deriveFont(Font.ITALIC);
        }
        header.setFont(baseFont);
        header.setBorder(new EmptyBorder(10, 0, 4, 0));
        return header;
    }

    private boolean isPhaseOptional(TrackerState state, int phaseNumber)
    {
        boolean sawPhase = false;
        for (int i = 0; i < state.size(); i++)
        {
            PhaseStep step = state.getStep(i);
            if (step.getPhaseNumber() != phaseNumber)
            {
                if (sawPhase)
                {
                    break;
                }
                continue;
            }
            sawPhase = true;
            if (!step.isOptional())
            {
                return false;
            }
        }
        return true;
    }

    private void updateActiveStepHighlight()
    {
        int activeIndex = trackerState.getActiveStepIndex();
        for (StepRow row : stepRows)
        {
            boolean isActive = (activeIndex != -1) && row.index == activeIndex;
            row.panel.setBackground(isActive ? ACTIVE_STEP_COLOR : ColorScheme.DARK_GRAY_COLOR);
            row.panel.setOpaque(true);

            PhaseStep step = trackerState.getStep(row.index);
            boolean checked = step.isChecked();
            row.checkbox.setSelected(checked);
            row.checkbox.setText(formatLabel(row.labelText, checked));

            if (checked)
            {
                row.checkbox.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
                row.checkbox.setFont(row.baseFont);
            }
            else if (row.isWarning)
            {
                row.checkbox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                row.checkbox.setFont(row.baseFont.deriveFont(Font.BOLD));
            }
            else
            {
                row.checkbox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                row.checkbox.setFont(row.baseFont);
            }
        }
        content.revalidate();
        content.repaint();
    }

    private void handleReset()
    {
        trackerState.reset();
        for (StepRow row : stepRows)
        {
            row.checkbox.setSelected(false);
        }
        updateActiveStepHighlight();
        if (onReset != null)
        {
            onReset.run();
        }
    }

    private static final class StepRow
    {
        private final int index;
        private final JPanel panel;
        private final JCheckBox checkbox;
        private final String labelText;
        private final Font baseFont;
        private final boolean isWarning;

        private StepRow(int index, JPanel panel, JCheckBox checkbox, String labelText, Font baseFont, boolean isWarning)
        {
            this.index = index;
            this.panel = panel;
            this.checkbox = checkbox;
            this.labelText = labelText;
            this.baseFont = baseFont;
            this.isWarning = isWarning;
        }
    }

    private String formatLabel(String labelText, boolean checked)
    {
        String safe = escapeHtml(labelText);

        if (!checked)
        {
            return "<html><div style='width:" + LABEL_WRAP_PX + "px'>" + safe + "</div></html>";
        }

        return "<html><div style='width:" + LABEL_WRAP_PX + "px'><span style='text-decoration: line-through;'>"
            + safe
            + "</span></div></html>";
    }

    private String escapeHtml(String text)
    {
        return text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
    }
}

package com.temporosstracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup("temporossSoloTracker")
public interface TemporossSoloTrackerConfig extends Config
{
    @ConfigItem(
        keyName = "stormNotifyNotification",
        name = "Storm notify",
        description = "Notification settings for storm intensity alerts"
    )
    default Notification stormNotifyNotification()
    {
        return Notification.ON;
    }

    @Range(min = 1, max = 99)
    @ConfigItem(
        keyName = "stormNotifyThreshold",
        name = "Storm notify threshold (%)",
        description = "Storm intensity threshold for notification"
    )
    default int stormNotifyThreshold()
    {
        return 92;
    }

    @ConfigItem(
        keyName = "autoReset",
        name = "Auto reset",
        description = "Auto-reset checkboxes when you return to the lobby"
    )
    default boolean autoReset()
    {
        return true;
    }

    @ConfigItem(
        keyName = "highlightCurrentStep",
        name = "Highlight current step",
        description = "Highlight the active step"
    )
    default boolean highlightCurrentStep()
    {
        return true;
    }
}
